package com.campusmart.entity;
import jakarta.persistence.*;import com.fasterxml.jackson.annotation.JsonIgnore;import java.time.LocalDateTime;
@Entity @Table(name="users",indexes=@Index(name="idx_user_email",columnList="email",unique=true)) public class User{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String fullName;@Column(nullable=false,unique=true)private String email;@Column(nullable=false)private String password;@Column(nullable=false)private String collegeName;@Column(nullable=false)private String studentId;@Enumerated(EnumType.STRING)@Column(nullable=false)private Role role=Role.STUDENT;@Column(nullable=false)private boolean verified;private String verificationCode;private LocalDateTime createdAt=LocalDateTime.now();public enum Role{STUDENT,ADMIN}public Long getId(){return id;}public String getFullName(){return fullName;}public void setFullName(String v){fullName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}@JsonIgnore public String getPassword(){return password;}public void setPassword(String v){password=v;}public String getCollegeName(){return collegeName;}public void setCollegeName(String v){collegeName=v;}public String getStudentId(){return studentId;}public void setStudentId(String v){studentId=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public boolean isVerified(){return verified;}public void setVerified(boolean v){verified=v;}@JsonIgnore public String getVerificationCode(){return verificationCode;}public void setVerificationCode(String v){verificationCode=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
